import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.B7PviQjB.js";const m=JSON.parse('{"title":"Concepts","description":"How workspaces, documents, folders, share links, templates, and the Trash fit together, and who can see and change what.","frontmatter":{"title":"Concepts","description":"How workspaces, documents, folders, share links, templates, and the Trash fit together, and who can see and change what.","type":"explanation"},"headers":[],"relativePath":"start/concepts.md","filePath":"start/concepts.md"}'),s={name:"start/concepts.md"};function n(i,e,h,d,l,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>Wafflebase keeps every document in a workspace, and workspace membership decides who can open it.</p><p><strong>Short answer:</strong> every member of a workspace can open and edit every document in it. Folders only organize. To give someone outside the workspace access to one document, send them a share link.</p><h2 id="workspaces" tabindex="-1">Workspaces <a class="header-anchor" href="#workspaces" aria-label="Permalink to &quot;Workspaces&quot;">​</a></h2><p>A workspace is a shared space for a team&#39;s documents. Your first sign-in creates one for you, and you can belong to several. Switch between them with the workspace menu at the top of the sidebar, which also has <strong>New workspace</strong>.</p><p>Each member has one of two roles:</p><table tabindex="0"><thead><tr><th>Role</th><th>Can do</th></tr></thead><tbody><tr><td>Member</td><td>Open, edit, copy, rename, and comment on every document in the workspace. Create viewer share links.</td></tr><tr><td>Owner</td><td>Everything a member can, plus invite and remove members, change the workspace name and URL, delete the workspace, and manage every document</td></tr></tbody></table><p>A document&#39;s author can also manage that document: move it, move it to the Trash, create editor links, and publish it as a template. Owners add people by creating an invite link in <strong>Settings</strong>. See <a href="/docs/collaborate/workspaces.html">Workspaces and roles</a>.</p><h2 id="documents" tabindex="-1">Documents <a class="header-anchor" href="#documents" aria-label="Permalink to &quot;Documents&quot;">​</a></h2><p>Everything in a workspace is a document. The type decides which editor opens it:</p><table tabindex="0"><thead><tr><th>Type</th><th>What it is</th></tr></thead><tbody><tr><td>Sheet</td><td>A spreadsheet with formulas, charts, and pivot tables</td></tr><tr><td>Document</td><td>A paged document for writing</td></tr><tr><td>Presentation</td><td>A slide deck</td></tr><tr><td>Note</td><td>A Markdown note</td></tr><tr><td>Board</td><td>An infinite canvas for sticky notes, shapes, and drawing</td></tr><tr><td>PDF, image, or file</td><td>An uploaded file you view, comment on (PDFs), and download, but don&#39;t edit</td></tr></tbody></table><p>Sheets, documents, presentations, notes, and boards save automatically as you type, and several people can edit one at the same time. They also keep a <a href="/docs/collaborate/version-history.html">version history</a> you can restore from.</p><h2 id="folders" tabindex="-1">Folders <a class="header-anchor" href="#folders" aria-label="Permalink to &quot;Folders&quot;">​</a></h2><p>Folders organize documents inside a workspace and can nest to any depth. They don&#39;t change who can open a document: a member sees every folder. Deleting a folder moves the documents inside it back to the workspace root. See <a href="/docs/collaborate/folders.html">Folders</a>.</p><h2 id="share-links" tabindex="-1">Share links <a class="header-anchor" href="#share-links" aria-label="Permalink to &quot;Share links&quot;">​</a></h2><p>A share link gives anyone who has it access to one document, without signing in or joining the workspace.</p><ul><li>A <strong>Viewer</strong> link lets people read the document. The editor shows a <strong>View only</strong> badge.</li><li>An <strong>Editor</strong> link lets people change it. Only the document&#39;s author or a workspace owner can create one.</li><li>A link can expire after 1 hour, 8 hours, 24 hours, or 7 days, or never (<strong>No limit</strong>).</li><li>People who open a link without signing in show as <strong>Anonymous</strong> to everyone else.</li></ul><p>Revoking a link stops it working at once. See <a href="/docs/collaborate/share.html">Share a document</a>.</p><h2 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h2><p>A template is a document published so others can start from it. Using a template makes a new copy in your workspace, so later changes on either side don&#39;t affect the other. A template can be visible to people with its link, to your workspace, or, after review, to everyone in the public gallery. See <a href="/docs/collaborate/templates.html">Templates</a>.</p><h2 id="trash" tabindex="-1">Trash <a class="header-anchor" href="#trash" aria-label="Permalink to &quot;Trash&quot;">​</a></h2><p>Moving a document to the Trash hides it everywhere, including its share links. A 10-second <strong>Undo</strong> appears right after. The document&#39;s author or a workspace owner can restore it from <strong>Trash</strong> in the sidebar, which brings its share links back, or delete it forever. Documents stay in the Trash until someone deletes them. See <a href="/docs/collaborate/trash.html">Trash</a>.</p><h2 id="what-this-means-for-you" tabindex="-1">What this means for you <a class="header-anchor" href="#what-this-means-for-you" aria-label="Permalink to &quot;What this means for you&quot;">​</a></h2><ul><li>To keep a document from a teammate, put it in a different workspace. A folder won&#39;t hide it.</li><li>To show one document to someone outside your team, send a viewer link rather than inviting them to the workspace.</li><li>If you can&#39;t choose <strong>Editor</strong> in the Share dialog, ask the document&#39;s author or a workspace owner to create the link.</li><li>If a document or a link vanished, look in the Trash before anything else.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/collaborate/workspaces.html">Workspaces and roles</a>: invite people and change workspace settings</li><li><a href="/docs/collaborate/share.html">Share a document</a>: create, copy, and revoke links</li><li><a href="/docs/collaborate/edit-together.html">Edit together</a>: see who else is working and where</li><li><a href="/docs/collaborate/trash.html">Trash</a>: restore or permanently delete documents</li></ul>',26)])])}const u=t(s,[["render",n]]);export{m as __pageData,u as default};
